# Let me check the 1970 JSON to see if there's data for earlier years
import json

with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# Search through all pages for Railroad
pages = data['document']['pages']
for i, page in enumerate(pages):
    content = json.dumps(page)
    if 'Railroad' in content and '1962' in content:
        print(f"Found on page {i}")
        # Print relevant section
        if 'tables' in page:
            for table in page['tables']:
                if isinstance(table, dict):
                    for k, v in table.items():
                        if '1962' in str(v) and 'Railroad' in str(v):
                            print(f"  Key: {k}")
                            break
